-- V19 replaces generic demand templates with game-specific structures and ready-to-sell service items.

SET @now = UTC_TIMESTAMP(6);

DELETE FROM service_categories WHERE game_code IN ('COD_WARZONE','CS2','VALORANT','APEX','DELTA_FORCE','FORTNITE','LOL','GTA5_ONLINE','GENSHIN','MARVEL_RIVALS','R6_SIEGE','WOW','DIABLO4','WUTHERING_WAVES','HONKAI_SR','ZZZ','ARC_RAIDERS','PUBG','WARFRAME','DESTINY2','MH_WILDS','TEKKEN8','STREET_FIGHTER6','NARAKA','EA_FC26','HONOR_KINGS');

ON DUPLICATE KEY UPDATE name=VALUES(name), icon_key=VALUES(icon_key), description=VALUES(description), is_active=VALUES(is_active), sort_order=VALUES(sort_order), updated_at=VALUES(updated_at);

ON DUPLICATE KEY UPDATE game_code=VALUES(game_code), name=VALUES(name), category=VALUES(category), short_desc=VALUES(short_desc), price_mode=VALUES(price_mode), price_fixed=VALUES(price_fixed), price_min=VALUES(price_min), price_max=VALUES(price_max), duration_text=VALUES(duration_text), status=VALUES(status), hot_score=VALUES(hot_score), manual_priority=VALUES(manual_priority), published_at=COALESCE(services.published_at, VALUES(published_at)), is_active=VALUES(is_active), sort_order=VALUES(sort_order), updated_at=VALUES(updated_at);

UPDATE service_categories SET name='DMZ / 撤离任务', description='DMZ、撤离、阵营任务与物资推进' WHERE game_code='CODMW4' AND code='DMZ';
